#pragma once
// CSCI 41 -- Lab 07: Linked Lists
//
// PROVIDED. Do not edit this file. Implement the functions in
// src/playlist.cpp.
//
// A CircularPlaylist is a circular, doubly linked list of song titles with
// a CURSOR marking the current song. Walking forward past the last song
// lands on the first one, with no special case: the structure does it.
//
// THE REPRESENTATION, stated once so every rule below is unambiguous:
//
//   - An EMPTY playlist has current_ == nullptr and size_ == 0.
//   - A non-empty playlist is a ring: every node has a real prev and a
//     real next, and there is no nullptr anywhere in it.
//   - A playlist of ONE node has that node pointing at itself in both
//     directions.
//   - current_ always points at a node in the ring, never at a freed one.
//
// Those four sentences are the class invariant. Assert them while you work.

#include <string>
#include <vector>

class CircularPlaylist {
public:
    CircularPlaylist();

    // Rule of Three (Day 10). This class owns its nodes, so the compiler's
    // versions are wrong and you must write all three.
    //
    // A copy has its OWN nodes, and its cursor sits on the copy of whatever
    // the original's cursor was on.
    CircularPlaylist(const CircularPlaylist& other);
    CircularPlaylist& operator=(const CircularPlaylist& other);
    ~CircularPlaylist();

    bool empty() const;          // true when there are no songs
    int  size() const;           // how many songs

    // Insert immediately AFTER the cursor. The cursor does NOT move.
    // On an empty playlist this adds the first song and the cursor lands
    // on it.
    void addAfterCurrent(const std::string& title);

    // Insert immediately BEFORE the cursor. The cursor does NOT move.
    // On an empty playlist this behaves exactly like addAfterCurrent.
    void addBeforeCurrent(const std::string& title);

    // Remove the song at the cursor.
    //   - empty playlist: change nothing and return false.
    //   - otherwise: remove it, move the cursor to the song that FOLLOWED
    //     it, and return true.
    //   - if it was the only song, the playlist becomes empty and the
    //     cursor becomes nullptr.
    bool removeCurrent();

    // Move the cursor one song forward / backward, wrapping round.
    // Return false on an empty playlist and change nothing.
    // On a playlist of one, both return true and the cursor stays put.
    bool next();
    bool prev();

    // The title at the cursor, or "" when the playlist is empty.
    std::string current() const;

    // Is this title anywhere in the playlist?
    bool contains(const std::string& title) const;

    // The next `count` titles starting AT the cursor, wrapping as needed.
    // Returns an empty vector when the playlist is empty or count <= 0.
    // The cursor does NOT move.
    //
    //   playlist A B C, cursor on A, snapshotForward(5)
    //       -> {"A", "B", "C", "A", "B"}
    std::vector<std::string> snapshotForward(int count) const;

    // Remove every song. Afterwards the playlist is empty and usable.
    void clear();

private:
    struct Node {
        std::string data;
        Node*       prev;
        Node*       next;
    };

    Node* current_;
    int   size_;

    // Suggested helper: make `other` a deep copy into this (already empty)
    // playlist. You do not have to use it.
    void copyFrom(const CircularPlaylist& other);
};
